/**
 * 대한민국 지도 데이터 (시·도 경계 + 시군구 좌표)
 * ---------------------------------------------------------------
 * - 시·도 경계(PROVINCES): 실측 좌표 기반 SVG 경로 17종
 * - 좌표 변환(project): 위경도 → SVG 좌표
 * - 시군구 좌표(SIGUNGU_COORDS): 전국 스케일 표시용 근사 중심좌표
 *   ※ 근사값이므로 정밀 위치가 필요하면 사업장 데이터에 lat/lng를 직접 넣으십시오.
 *      (사업장의 lat/lng가 있으면 그 값이 항상 우선 적용됩니다)
 */

export interface ProvinceShape {
  /** 시·도명 (예: 충청남도) */
  name: string;
  /** SVG path 데이터 */
  d: string;
  /** 라벨 표기용 중심 좌표 */
  cx: number;
  cy: number;
}

export const KR_VIEWBOX = { w: 448, h: 796 } as const;

/** 위경도 → SVG 좌표 변환 계수 */
const TF = {
  lngMin: 125.90001169362641,
  latMax: 38.61370930709446,
  kx: 111.9577289450663,
  ky: 138.1478200843704,
  pad: 18,
} as const;

/** 위경도를 지도 SVG 좌표로 변환한다. */
export function project(lng: number, lat: number): { x: number; y: number } {
  return {
    x: (lng - TF.lngMin) * TF.kx + TF.pad,
    y: (TF.latMax - lat) * TF.ky + TF.pad,
  };
}

