/** 지도에 존재하는 시·도명 집합 */
const PROVINCE_NAMES = new Set(KR_PROVINCES.map(p => p.name));

/**
 * 임의의 시·도 표기를 지도 경로의 정식 명칭으로 정규화한다.
 * 예) '충남' → '충청남도', '강원특별자치도' → '강원도'
 */
export function normalizeProvince(raw?: string | null): string | null {
  if (!raw) return null;
  const s = raw.trim();
  if (PROVINCE_NAMES.has(s)) return s;
  if (PROVINCE_ALIASES[s]) return PROVINCE_ALIASES[s];
  // 부분 일치 (예: '충청남도 당진시' 형태로 들어온 경우)
  for (const name of PROVINCE_NAMES) {
    if (s.startsWith(name)) return name;
  }
  for (const [alias, canonical] of Object.entries(PROVINCE_ALIASES)) {
    if (s.startsWith(alias)) return canonical;
  }
  return null;
}

/**
 * 시·도 + 시군구 이름으로 근사 좌표를 조회한다.
 * 시·도를 모르면 전체 표를 훑어 시군구명으로 찾는다.
 */
export function lookupSigungu(
  province?: string | null,
  sigungu?: string | null,
): { lng: number; lat: number; province: string } | null {
  if (!sigungu) return null;
  const key = sigungu.trim();
  const prov = normalizeProvince(province);

  if (prov && SIGUNGU_COORDS[prov]?.[key]) {
    const [lng, lat] = SIGUNGU_COORDS[prov][key];
    return { lng, lat, province: prov };
  }
  // 시·도 미상 → 전체 검색 (동명 시군구는 첫 일치를 사용)
  for (const [pName, table] of Object.entries(SIGUNGU_COORDS)) {
    if (table[key]) {
      const [lng, lat] = table[key];
      return { lng, lat, province: pName };
    }
  }
  return null;
}

/** SVG 좌표를 위경도로 역변환한다. (지도 클릭 → 좌표 산출용) */
export function unproject(x: number, y: number): { lng: number; lat: number } {
  return {
    lng: (x - TF.pad) / TF.kx + TF.lngMin,
    lat: TF.latMax - (y - TF.pad) / TF.ky,
  };
}
